#!/bin/bash
# LAB-7: checkout refuses expired / unrecorded devices, allows the due date itself.
fail=0
f=$(mktemp); c=$(mktemp)
printf 'OSC-1\t2027-04-30\nOSC-2\t2026-10-31\n' > "$c"
run() { CALIB=$c LOANS=$f bash bin/checkout "$@" 2>&1; }

run OSC-1 t 2026-11-01 >/dev/null || { echo "valid device refused"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "valid not recorded"; fail=1; }
: > "$f"
run OSC-2 t 2026-10-31 >/dev/null || { echo "due date itself refused"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "due date not recorded"; fail=1; }
: > "$f"
run OSC-2 t 2026-11-01 >/dev/null && { echo "expired allowed"; fail=1; }
run NOPE-9 t 2026-11-01 >/dev/null && { echo "unrecorded allowed"; fail=1; }
[ ! -s "$f" ] || { echo "refused loan was recorded"; fail=1; }
rm -f "$f" "$c"
exit $fail

