#!/bin/bash
fail=0
f=$(mktemp)
out=$(LOANS=$f bash bin/checkout DMM-3 test 2026-11-01)
[ "$out" = "checked out DMM-3 to test" ] || { echo "checkout output"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "checkout appends"; fail=1; }
# due date itself is allowed
: > "$f"
LOANS=$f bash bin/checkout OSC-2 test 2026-10-31 >/dev/null || { echo "due day allowed"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "due day recorded"; fail=1; }
# expired, unrecorded: error and no record
for case in "OSC-2 2026-11-01" "FG-5 2026-11-01"; do
  : > "$f"
  set -- $case
  LOANS=$f bash bin/checkout "$1" test "$2" >/dev/null 2>&1 && { echo "$1 must be refused"; fail=1; }
  [ ! -s "$f" ] || { echo "$1 must not be recorded"; fail=1; }
done
rm -f "$f"
exit $fail
